using System;using System.IO;using System.Linq;using System.Text;using System.Drawing;using System.Collections.Generic;using System.Windows.Forms;using System.Windows.Media.Media3D;
namespace GearLab {public static class AuthorDesign65Tests {
 public static int Run(string folder){Directory.CreateDirectory(folder);var log=new StringBuilder();int count=0;Action<bool,string> check=(ok,name)=>{if(!ok)throw new Exception(name);count++;log.AppendLine("PASS "+name);};try{
  var d=AuthorDesign65.Create();d.Save(Path.Combine(folder,"author65-default.robot.json"));check(d.Validate().Count==0,"valid new preset");check(d.AuthorDesign.Height==1000&&d.Joints.Last().Payload==.3,"1000 mm and 300 g default");check(d.Joints.All(j=>j.MotorFrame==42.3&&j.MotorShaft==5&&j.MotorLength==44),"latest user motor envelope replaces old STEP measurements");check(d.Joints.All(j=>j.MotorTorque==0&&j.MotorMass==.29),"motor working torque remains unknown; mass uses user estimate");check(d.Joints.Count==7&&d.Joints.All(j=>j.CustomAxis!=null),"seven explicit reference motion groups");
  check(d.FormatVersion==2,"extended reference uses a format older apps reject safely");var oldFormat=d.Clone();oldFormat.FormatVersion=1;check(oldFormat.Validate().Count>0,"extended geometry cannot be mislabeled as legacy format 1");
  var b=RobotCad.Build(d);check(b.Model.Valid,"reference builds without native CAD worker");check(b.Entries.Count==21,"17 author meshes and four cable curves preserved");check(b.Model.Parts.All(part=>PartMotion.Bind(new Result{P=new Parameters(),Model=b.Model,Robot=b},part).Kind=="robot"),"mesh-only author parts bind motion without fake CAD sections");check(b.Entries.Values.All(e=>!e.Printable&&e.Part.Reference),"unverified source is never printable");check(b.Model.Parts.All(p=>!PrintExport.Candidate(p)),"reference excluded from print selector");
  var all=b.Entries.Values.SelectMany(e=>e.Part.MeshOverride.Points.Select(p=>e.Part.Placement.Transform(p))).ToArray();double min=all.Min(p=>p.Z),height=all.Max(p=>p.Z)-min;check(Math.Abs(min)<.001&&Math.Abs(height-1000)<.05,"normalization uses floor zero and one metre posed height");
  var half=AuthorDesign65.Create(500,.6);var h=RobotCad.Build(half);check(h.Model.Valid,"500 mm variant builds");check(Math.Abs(h.Entries.Values.SelectMany(e=>e.Part.MeshOverride.Points.Select(p=>e.Part.Placement.Transform(p))).Max(p=>p.Z)-500)<.05,"height changes actual geometry");check(half.Joints.Last().Payload==.6,"payload change stored independently");
  foreach(var e in b.Entries.Values){var eh=h.Entries[e.Id];var p=e.Part.Placement.Transform(e.Part.MeshOverride.Points[0]);var q=eh.Part.Placement.Transform(eh.Part.MeshOverride.Points[0]);check((q-new Point3D(p.X*.5,p.Y*.5,p.Z*.5)).Length<.001,"uniform scale "+e.Id);}
  var again=RobotDocument.Parse(d.Serialize());check(again.AuthorDesign.Asset.Parts.Count==21&&again.Validate().Count==0,"portable project embeds reference without original blend");check(RobotCad.Build(again).Model.Parts.Count==21,"portable project reconstructs all parts");
  var fixedId="author65_Cylinder_027";var baseBefore=b.Pose(fixedId,0,false);var first=b.Entries.Values.First(e=>!e.InputSide&&e.JointId==d.Joints[0].Id);var before=b.Pose(first.Id,0,false).Transform(first.Part.MeshOverride.Points[0]);d.Joints[0].Position=15;b.InvalidatePose();var after=b.Pose(first.Id,0,false).Transform(first.Part.MeshOverride.Points[0]);check((after-before).Length>1,"base rotation moves attached author mesh");check(b.Pose(fixedId,0,false)==baseBefore,"floor base remains fixed during base rotation");
  var clone=again.Clone();var fk0=RobotKinematics.Evaluate(clone,0,false);clone.Joints[3].Position=10;var fk1=RobotKinematics.Evaluate(clone,0,false);check((fk0[clone.Joints[5].Id].Origin-fk1[clone.Joints[5].Id].Origin).Length>1,"elbow moves wrist descendants");check((fk0[clone.Joints[1].Id].Origin-fk1[clone.Joints[1].Id].Origin).Length<1e-8,"elbow leaves shoulder ancestor fixed");
  var analysis=RobotSolver.Solve(RobotCad.Build(again));check(!analysis.Valid&&analysis.Joints.All(j=>!j.Enough),"unknown arm mass cannot receive a passing engineering result");var loaded=again.Clone();loaded.Joints.Last().Payload=.6;var load2=RobotSolver.Solve(RobotCad.Build(loaded));check(Math.Abs(load2.Joints[1].Required-analysis.Joints[1].Required*2)<1e-8&&analysis.Joints[1].Required>0,"payload-only torque doubles when payload doubles");
  bool blocked=false;try{b.ForExport(true,null);}catch{blocked=true;}check(blocked,"print export rejects unfinished source");blocked=false;try{b.ForExport(false,null);}catch{blocked=true;}check(blocked,"STEP export does not pretend source mesh is solid CAD");
  foreach(var axis in new[]{new[]{0.0,0,0},new[]{double.NaN,0,1},new[]{1.0,2},new[]{double.PositiveInfinity,0,0}}){var bad=again.Clone();bad.Joints[0].CustomAxis=axis;check(bad.Validate().Count>0,"reject malformed custom axis");}
  var badRef=again.Clone();badRef.AuthorDesign.Asset.Parts[0].Joint=99;check(badRef.Validate().Count>0,"reject out-of-range mesh owner");badRef=again.Clone();badRef.Joints.RemoveAt(4);check(badRef.Validate().Count>0,"deleting a source joint cannot silently rebind geometry");badRef=again.Clone();badRef.AuthorDesign.Height=double.NaN;check(badRef.Validate().Count>0,"reject invalid height");
  var oversized=again.Clone();oversized.AuthorDesign.Asset.Parts[0].Preview="cw7wNfnoycTAzMDAAAA=";check(!RobotCad.Build(oversized).Model.Valid,"reject oversized compressed mesh before allocating coordinates");
  var language=AppSettings.Current.Language;try{AppSettings.SetLanguage(GearLanguage.English);check(I18n.T(AuthorDesign65.Notice).StartsWith("Author design"),"new design warning translates to English");check(AuthorDesign65.Report(again).Contains("Payload:")&&!AuthorDesign65.Report(again).Contains("Нагрузка"),"new audit opens in English");AppSettings.SetLanguage(GearLanguage.Русский);check(AuthorDesign65.Report(again).Contains("Груз:"),"new audit switches back to Russian");}finally{AppSettings.SetLanguage(language);}
  var legacy=RobotDocument.Example();check(legacy.Validate().Count==0&&legacy.Joints.All(j=>j.CustomAxis==null),"legacy cardinal axes remain supported");check(RobotCad.Build(legacy).Model.Valid,"legacy robot still builds");
  File.WriteAllText(Path.Combine(folder,"author65-results.txt"),log+"PASS "+count+" assertions",Encoding.UTF8);return 0;
 }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"author65-error.txt"),log+ex.ToString(),Encoding.UTF8);return 1;}}
 public static int View(string folder){Directory.CreateDirectory(folder);try{using(var robot=new RobotDesignerForm())using(var shell=new WorkspaceShell(robot)){var move=(ToolStripButton)typeof(RobotDesignerForm).GetField("move",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(robot);move.Checked=true;robot.SetDocument(AuthorDesign65.Create());if(move.Checked||move.Enabled)throw new Exception("Reference import did not reset move mode safely");shell.Show();var timer=System.Diagnostics.Stopwatch.StartNew();while((!robot.WebScene.Ready||!robot.Scene.Ready)&&timer.Elapsed.TotalSeconds<45){Application.DoEvents();System.Threading.Thread.Sleep(20);}if(!robot.WebScene.Ready||!robot.Scene.Ready)throw new Exception("Reference view did not initialize: WPF="+robot.Scene.Ready+" Web="+robot.WebScene.Ready+" Error="+robot.Scene.Error+" Model="+string.Join("; ",robot.Build.Model.Errors));robot.SetStage(2);robot.WebScene.Send(new{type="presentation",enabled=true});robot.WebScene.Send(new{type="preset",view="REFERENCE"});for(int n=0;n<60;n++){Application.DoEvents();System.Threading.Thread.Sleep(20);}var task=robot.WebScene.SavePreview(Path.Combine(folder,"new-design-1000mm.png"));while(!task.IsCompleted){Application.DoEvents();System.Threading.Thread.Sleep(10);}task.GetAwaiter().GetResult();File.WriteAllText(Path.Combine(folder,"author65-view-results.txt"),"PASS reference import resets old move mode; WPF and WebView2 initialize; 1000 mm source reference rendered.");shell.ApproveTestClose();shell.Close();}return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"author65-view-error.txt"),ex.ToString());return 1;}}
}}

